files.tests/test_client.py:
from app.client import fetch_name

class Response:
    def json(self):
        return {'name': 'Ada'}

class PendingResponse:
    def __await__(self):
        if False:
            yield None
        return Response()

class Client:
    def get(self, path):
        return PendingResponse()

def test_awaits_response():
    operation = fetch_name(Client())
    try:
        operation.send(None)
    except StopIteration as completed:
        result = completed.value
    else:
        raise AssertionError('fetch_name did not finish')
    assert result == 'Ada'

